<?php require __DIR__.'/app/bootstrap.php';if(empty($_SESSION['customer_id'])){header('Location: '.url('account.php'));exit;}$no=trim($_GET['order']??'');$s=db()->prepare('SELECT order_number,total,status FROM orders WHERE order_number=? AND customer_id=?');$s->execute([$no,$_SESSION['customer_id']]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found');}$pageTitle='Order Received — NEXT TECH';require __DIR__.'/includes/header.php';?><section class="success-panel"><div class="success-icon">✓</div><span class="eyebrow">ORDER RECEIVED</span><h1>Thank you for your order!</h1><p>Your order number is <strong><?=e($order['order_number'])?></strong>.</p><h2><?=money($order['total'])?></h2><p>Payment: Cash on Delivery. Our team will contact you to confirm delivery details.</p><a class="btn btn-primary" href="<?=e(url('account.php'))?>">View My Orders</a></section><?php require __DIR__.'/includes/footer.php';?>